{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'n' p, span_name, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','OrderOtherRepository.findByAccountId') GROUP BY ALL UNION ALL SELECT 'a', span_name, count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','OrderOtherRepository.findByAccountId') GROUP BY ALL ORDER BY span_name, p",
          "claim": "The SELECT ts.orders_other DB span p95 rose from 0.4ms to about 418ms; the parent repository span rose similarly."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'a' p, span_name, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('Session.find other.entity.Order','Session.merge other.entity.Order','OrderOtherRepository.save') GROUP BY ALL",
          "claim": "ORM session and save spans stay near 1ms while the raw SELECT DB spans take about 420ms, so the slowdown is in DB calls."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'n' p, metric, round(avg(value),2) avgv FROM normal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set') GROUP BY ALL UNION ALL SELECT 'a', metric, round(avg(value),2) FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set') GROUP BY ALL",
          "claim": "Order-other pod CPU and memory are flat or lower during the incident, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'n' p, service_name, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM normal_traces WHERE service_name='ts-admin-order-service' AND span_name LIKE 'GET /api/v1/adminorderservice%' GROUP BY ALL UNION ALL SELECT 'a', service_name, count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-admin-order-service' AND span_name LIKE 'GET /api/v1/adminorderservice%' GROUP BY ALL",
          "claim": "Admin-order GET requests, which call order-other, rose from about 14ms to about 1050ms p95."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'a' p, service_name, span_name, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name LIKE 'SeatController%' GROUP BY ALL",
          "claim": "Seat-service left-tickets handling is about 220ms p95 while its own time stays flat, meaning the delay comes from its callee order-other."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'n' p, span_name, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY ALL UNION ALL SELECT 'a', span_name, count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY ALL",
          "claim": "Travel2 trips/left p95 rose from about 62ms to about 269ms, consistent with waiting on seat-service."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'a' p, service_name, span_name, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY ALL",
          "claim": "Travel-plan POST endpoints remain elevated during the incident, consistent with waiting on seat-service."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'n' p, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%travel2%' GROUP BY ALL UNION ALL SELECT 'a', count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%travel2%' GROUP BY ALL",
          "claim": "The dashboard's calls to travel2 rose from about 50ms to about 215ms p95."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'n' p, count(*) c, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%admin%order%' GROUP BY ALL UNION ALL SELECT 'a', count(*), round(approx_quantile(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%admin%order%' GROUP BY ALL",
          "claim": "The dashboard's calls to admin-order rose from about 14ms to about 1000ms p95."
        }
      ]
    }
  ]
}
